ALTER TABLE contract_templates DROP INDEX serviceType;

-- Step 2: Add projectType column with default 'default'
ALTER TABLE contract_templates ADD COLUMN projectType VARCHAR(64) NOT NULL DEFAULT 'default' AFTER serviceType;

-- Step 3: Add new composite unique index on (serviceType, projectType)
ALTER TABLE contract_templates ADD UNIQUE INDEX serviceType_projectType_unique (serviceType, projectType);

